/** URL of a command's preview, if it exists (to set as `data-preview` on the button). */
export const previewUrl = (commandId: string) =>
  previews[commandId] ? `${import.meta.env.BASE_URL}previews/${previews[commandId]}` : undefined;

/** Hover delay before showing the preview. */
const DELAY = 700;

/**
 * Video tooltip: after a prolonged hover over a `[data-preview]` element, plays the preview
 * in a loop below the button. A single instance, mounted once (event delegation).
 */
export function HoverPreview() {
  const [shown, setShown] = createSignal<{ src: string; label: string; x: number; y: number }>();
  let timer: number | undefined;
  let target: HTMLElement | undefined;

  const hide = () => {
    clearTimeout(timer);
    target = undefined;
    setShown(undefined);
  };
  const over = (e: PointerEvent) => {
    const el = (e.target as Element | null)?.closest<HTMLElement>("[data-preview]");
    if (el === target) return;
    hide();
    // Disabled buttons included: the preview shows what to select to enable them.
    if (!el) return;
    target = el;
    timer = window.setTimeout(() => {
      const r = el.getBoundingClientRect();
      const x = Math.min(Math.max(8, r.left + r.width / 2 - 130), window.innerWidth - 268);
      setShown({ src: el.dataset.preview!, label: el.dataset.previewLabel ?? el.textContent ?? "", x, y: r.bottom + 6 });
    }, DELAY);
  };

  onMount(() => {
    document.addEventListener("pointerover", over);
    document.addEventListener("pointerdown", hide, true);
    document.addEventListener("keydown", hide, true);
    window.addEventListener("blur", hide);
  });
  onCleanup(() => {
    hide();
    document.removeEventListener("pointerover", over);
    document.removeEventListener("pointerdown", hide, true);
    document.removeEventListener("keydown", hide, true);
    window.removeEventListener("blur", hide);
  });

  return (
    <Show when={shown()}>
      {(p) => (
        <div class="hover-preview" style={{ left: `${p().x}px`, top: `${p().y}px` }} role="tooltip">
          <video src={p().src} autoplay loop muted playsinline width="240" height="150" />
          <div class="hover-preview-label">{p().label}</div>
        </div>
      )}
    </Show>
  );
}
